  "breakdown.hint": "Zerk hartzen duen lekua babeskopia berrienean, handiena lehenengo, eta horretatik zenbat ekarri duen azken babeskopiak berri edo aldatuta. Aldatutako fitxategi batek bere tamaina osoarekin zenbatzen du, restic-ek ez baitu esaten zenbat aldatu den. Tamainak fitxategien tamainak dira, bikoizketa kendu eta konprimitu aurretik. BombVault-ek biltegiaren indizetik irakurtzen ditu, fitxategiak irakurri gabe, eta babeskopia bakoitzaren ondoren eguneratzen ditu.",
