  // Settings
  "settings.title": "Ezarpenak",
  "settings.encryptionPasswordWhere":
    "Pasahitz hori ez duzu inoiz idazten: BombVault-ek APP_KEY-tik eratortzen du dei bakoitzean. Balioa bera zure berreskurapen-kitean dago, eratorritako restic pasahitz gisa, eta hori behar duzu restic eskuz exekutatzeko biltegi baten aurka.",
  "settings.encryptionHint": "Zifratzea biltegi bakoitzeko finkatzen da sortzean, beraz ezarpen honek biltegi BERRI bat nola sortzen den baino ez du erabakitzen. Dagoeneko dagoen batentzat, BombVault-ek modua biltegitik bertatik irakurtzen du. Ikus Berrezarpen orria. Hau dagoen biltegi baten aurka aldatzeak restic-ek ireki ez dezan eragiten du, besterik ez.",

  // Encryption-key recovery kit
  "recovery.title": "Berreskuratze-kita",
  "recovery.download": "Deskargatu berreskuratze-kita",
  "recovery.why": "Zifratzea aktibatuta dagoenean, zure APP_KEY da babeskopia bakoitzaren sekretu nagusia. Deskargatu berreskuratze-kit bat (gakoa, eratorritako restic pasahitza, biltegien kokapenak eta eskuzko berrezarpen-urratsak) BombVault edukiontzi bat abian izan gabe ere berrezarri ahal izateko. Gorde konexiorik gabe eta modu seguruan.",
  "recovery.nagTitle": "Gorde zure berreskuratze-kita",
  "recovery.nagBody": "Kitik gabe ezin dituzu zure babeskopia zifratuak ireki guztia galdu ondoren.",
