  "settings.pathMode.local": "Lokala",
  "settings.compression": "Konpresioa",
  "settings.compressionInfo": "Nola biltzen dituen restic-ek datu berriak biltegi honetan. Automatikoa restic-en lehenetsia da eta datu gehienetarako balio du. Gehienezkoak leku gehiago aurrezten du eta CPU denbora gehiago kostatzen du babeskopietan eta kopietan. Desaktibatuta aukerak datuak konprimitu gabe gordetzen ditu, eta hori lagungarria da dagoeneko konprimituta daudenean, bideoak edo argazkiak adibidez. 1. bertsioko formatu zaharreko biltegi batek ezin du konprimitu eta ezarpen hau ez du kontuan hartzen.",
