  "settings.primaryRemote.hint": "Babeskopia-bide hau urruneko restic biltegi bat da: kopia NAGUSIA DA, ez erreplika bat. Konfiguratu hemen banda-zabaleraren mugak, gehitu-soilik babesa eta hazkunde-aurrekontuaren alarma, kanpoko kopia batek jasotzen duen babes bera.",
