  "settings.offsiteHint": "Babeskopia lokal arrakastatsu bakoitzaren ondoren, bigarren biltegi batera ere errepikatzen du restic copy erabiliz. Sartu urruneko helbide bat (rest:http://host:8000/repo, s3:…) edo bide lokal bat; utzi hutsik desgaitzeko. Babeskopia lokala nagusia izaten jarraitzen du.",
