  "offsite.immutable": "Aldaezina (gehitu-soilik)",
  "offsite.immutableHint": "BombVaultek kanpokoa garbitzeari/ezabatzeari uzten dio eta beste aldeak zaintzapena ezartzen uzten dio. Beste aldeak ezabatzeak benetan ukatu behar ditu, beheko horretan egiaztatua.",
  "offsite.rcloneWarning": "rclone serve restic --append-only-k iturriarekin saiakera-akats ireki bat du, eta gehitutakoak gal ditzake. Kanpoko aldaeziltasunerako rest-server gomendatzen da.",
  "offsite.s3Unverified": "Oharra: S3ren gehitu-soilik ezin da automatikoki egiaztatu. Konfiguratu bucketaren bertsionatzea + ezabatze-debekua eskuz; markadorea eremu hau egiaztatu gabe gisa jarraituko du.",
