  "dest.group.fromGroup": "Zure taldetik",
  "dest.groupTip.fromGroup": "Zure taldeko instantziek append-only moduan exekutatzen dituzten hartzaile-zerbitzariak. Bat hautatzean, bere helbidea eta instantzia honen saio-hasiera propioa betetzen dira. Gero probatu konexioa beste edozein helmugarekin bezala.",
  "dest.receiver.needsAddress": "helbide zuzena behar du",
  "dest.receiver.needsAddressTip": "Instantzia honek besteraino bitartekariaren bidez soilik iristen da, eta bitartekariak ez ditu babeskopiak garraiatzen. Gehitu instantzia horren helbidea hemen: Ezarpenak, Parekatzea.",
  "dest.group.cloud": "Hodeiko biltegiratzea",
  "dest.fit.best": "aukerarik onena",
  "dest.fit.good": "aukera ona",
  "dest.fit.slower": "badabil, baina motelago",
  "dest.groupTip.storage": "Sarbide-gako batekin atzitzen diren bucketak. Azkarrak, terabyteko merkeak, eta object lock-ekin bertsio zaharrak bizirik irauten dute norbaitek ezabatzen baditu ere.",
  "dest.groupTip.selfs3": "Zure hardwarean exekutatzen duzun S3 zerbitzari bat, adibidez bigarren Unraid ekipo bat senide baten etxean.",
  "dest.groupTip.server": "Zuk kudeatzen edo alokatzen duzun makina bat: bigarren NAS bat, Hetzner Storage Box bat, beste nonbait dagoen Raspberry Pi bat.",
  "dest.groupTip.cloud": "Dokumentu eta argazkietarako egindako zerbitzuak. Eskaera asko mugatzen dituzte, beraz lehen babeskopiak eta garbiketak gehiago irauten dute.",
  "dest.note.slower": "Badabil, baina motelago. {name} zerbitzuak eskaera asko mugatzen ditu, beraz lehen babeskopiak eta garbiketak askoz gehiago irauten dute hemen biltegiratze-zerbitzu batean baino.",
  "dest.note.dailyCap": "Google Drivek egunean gehienez 750 GB igoera onartzen ditu.",
  "dest.note.selfHosted": "Zure zerbitzarian exekutatzen da eta bere konexioa bezain azkarra da.",
  "dest.note.rest": "Kanpoko kopietarako lehen aukera: append-only moduko rest-server batek berak ukatzen du ezabatzea, eta BombVaultek hori egiaztatu dezake.",
  "dest.note.good": "Babeskopietarako egokia.",
  "dest.note.lock": "Hemen ezabatzearen aurkako babesa posible da.",
  "dest.name": "Izena",
  "dest.nameHint": "Botoietan erakusten da. Geroago alda daiteke.",
  "dest.token.run": "Exekutatu hau nabigatzailea duen ordenagailu batean eta hasi saioa",
  "dest.token.tip": "BombVault nabigatzailerik gabeko zerbitzari batean exekutatzen da. rclonek saio-hasiera zure ordenagailuan irekitzen du eta gero token bat inprimatzen du, beheko eremuan sartzeko. Windows, macOS eta Linuxerako rclone rclone.org helbidean dago.",
  "dest.sshKey": "Gehitu BombVaulten SSH gako publikoa zerbitzariari",
  "dest.sshKey.tip": "BombVaultek VM babeskopietarako SSH bidez erabiltzen duen gako bera. Gakoa jarrita pasahitzik ez da behar, eta pasahitzarekin saioa hastea desaktiba daiteke zerbitzarian.",
  "dest.appPassword.tip": "Bi urratseko saio-hasiera aktibatuta dagoenean, pasahitz normalak ez du balio. Sortu aplikazio-pasahitz bat zure kontuaren segurtasun-ezarpenetan.",
  "dest.key.note": "Gakoak zifratuta gordetzen dira beste hodei-kredentzialekin batera. Bucket honetarako soilik den gako bat kontuaren gako nagusia baino seguruagoa da.",
  "dest.more": "Ezarpen gehiago",
