  "dest.free": "{size} libre",
  "dest.location": "Kanpoko biltegia",
  "dest.route.s3": "S3 zerbitzuek resticen S3 backend propioa erabiltzen dute rclonen ordez, eta horri esker biltegiratze-klasea eta object lock aplika daitezke.",
  "dest.route.rclone": "restic zerbitzu honetara BombVaultek ekartzen duen rclone bidez iristen da. Urruneko konexioa orduan Ezarpenak, Helmugak ataleko rclone.conf-ean agertzen da.",
  "dest.route.rest": "restic zuzenean mintzatzen da rest-serverrekin.",
  "dest.route.path": "Ostalariaren datu-muntaketaren azpiko karpeta bat.",
  "dest.lock.s3": "Aktibatu bertsionatzea eta object lock bucketean. Bertsio zaharrak bizirik irauten dute orduan norbaitek gakoarekin ezabatzen badu ere. BombVaultek ezin du hori oraindik egiaztatu {name} zerbitzurako.",
  "dest.lock.none": "{name} ezin da ezabatzeari uko egin. Zure zerbitzarira sartzen dena kanpoko biltegi honetara ere sartzen da. Ransomwarearen aurka rest-server bat edo object lock duen biltegiratze-zerbitzu bat lagungarri da, adibidez bigarren helmuga gisa.",
  "dest.lock.rest": "Gorde ondoren, domeinuaren txartelaren manipulazio-probak zerbitzariak ezabatzeari uko egiten diola egiaztatzen du.",
  "dest.recovery": "Berreskuratze-kitak helmuga hau zerrendatzen du, azpian dagoen domeinu bakoitzaren biltegiarekin. Saio-hasiera bera BombVaulten ezarpenen babeskopiarekin itzultzen da; hori gabe, zerbitzari berrian berriro sartzen da.",
  "dest.recovery.token": "{name} etengabe berritzen du bere sarbidea, beraz ezarpen-babeskopia zahar bateko token bat iraungita egon liteke. Orduan hasi saioa berriro behin. Biltegiari berari ez dio eragiten.",
  "dest.recovery.ssh": "SSH gakoa ere ezarpen-babeskopiarekin itzultzen da. Hori gabeko instalazio berri batean, gako berria zerbitzarian jarri behar da.",
