  // Retention
  "excludes.advisoryImmichDb": "Immichek argazki bakoitzaren albumak, aurpegiak eta datak PostgreSQL datu-base batean gordetzen ditu, eta datu-base hori bere edukiontzi bereizian exekutatzen da, beraz babeskopia honek ez du barne hartzen. Hemendik berrezartzeak argazkiak itzultzen ditu, baina horrelakorik gabe. BombVaultek datu-base horren edukiontzia automatikoki irauliko du babeskopia egiten zaionean, beraz egiaztatu zure egutegian sartuta dagoela.",
  "excludes.advisoryNextcloudDb": "Nextcloudek kontuak, partekatzeak eta etiketak datu-base batean gordetzen ditu, eta datu-base hori normalean edukiontzi bereizi batean exekutatzen da, beraz babeskopia honek ez du barne hartzen. Fitxategiak itzultzen dira, partekatzeak ez. BombVaultek datu-base horren edukiontzia automatikoki irauliko du babeskopia egiten zaionean, beraz egiaztatu zure egutegian sartuta dagoela.",
