  "excludes.presetHint.trickplay": "Erreprodukzio-barrarako irudiak. Programatutako ataza batek berriro sortzen ditu leheneratu ondoren.",
  "excludes.presetHint.metadata": "Aplikazioak deskargatutako kartelak eta irudiak. Metadatuak freskatzean berriro lortzen dira, baina zuk zeuk igotako irudiak ere hemen daude eta galdu egingo lirateke. Sarrera hau desaktibatuta hasten da.",
