  "excludes.presetHint.models": "Ikasketa automatikoko ereduak. Aplikazioak berriro deskargatzen ditu abiaraztean.",
  "rcloneRemote.heading": "Gehitu SMB edo WebDAV helmuga",
  "rcloneRemote.hint": "Windows edo Samba partekatze batera iristen da, edo WebDAV zerbitzari batera (Nextcloud, adibidez), ostalarian muntatu gabe. restic-ek ez du gomendatzen biltegi bat muntatutako CIFS partekatze batean gordetzea, eta modu honek muntaketa guztiz saihesten du. Pasahitza rclone-ri ematen zaio, bere formatuan gorde dezan, eta ez da inoiz testu argian gordetzen. NFS ez da hemen eskaintzen, ez restic-ek ez rclone-k ez dutelako onartzen: NFSrako, muntatu esportazioa Unraid-en eta ezarri babeskopia-bide bat hara.",
