  "dbdump.saveHint": "Iraulketa fitxategi gisa idazten du zerbitzariko aukeratutako karpetan, nobody:users jabe dela, sareko partekatzetik ireki ahal izateko. Fitxategiak taula guztiak eta datu-baseko erabiltzaileen pasahitz-hashak ditu; gorde ezazu zuk bakarrik iristen zaren lekuan.",
  "dbdump.saveCancelHint": "Bertan behera uzteak gordetzea gelditzen du eta amaitu gabeko fitxategia kentzen du.",
  "dbdump.savedTo": "Hemen gorde da: {path}",
  "dbdump.import": "Inportatu datu-base berri batean",
  "dbdump.importConfirm": "{engine} {version} iraulketa hau {container}-en inportatu? BombVault-ek edukiontzia gelditzen du, bere datuen karpeta alde batera eramaten du (gorde egiten da, ez da ezer ezabatzen), edukiontzia datuen karpeta hutsarekin abiarazten du eta iraulketa inportatzen du. Datu-base hau erabiltzen duten aplikazioek iraulketaren uneko egoera ikusiko dute.",
  "dbdump.importConfirmNoVersion": "{engine} iraulketa hau {container}-en inportatu? BombVault-ek edukiontzia gelditzen du, bere datuen karpeta alde batera eramaten du (gorde egiten da, ez da ezer ezabatzen), edukiontzia datuen karpeta hutsarekin abiarazten du eta iraulketa inportatzen du. Datu-base hau erabiltzen duten aplikazioek iraulketaren uneko egoera ikusiko dute.",
  "dbdump.importNoVersion": "Iraulketa honek ez du bere datu-basearen bertsioa jasotzen. Inportazioak huts egingo du zerbitzariak irakurri ezin badu.",
  "dbdump.importStops": "one=Inportatzen duen bitartean, BombVault-ek {apps} ere gelditzen du eta gero berriro abiarazten. Inportazioak hasi ondoren huts egiten badu, datu zaharrak alde batera geratzen dira eta aplikazioa geldituta.|other=Inportatzen duen bitartean, BombVault-ek aplikazio hauek ere gelditzen ditu: {apps}. Gero berriro abiarazten ditu. Inportazioak hasi ondoren huts egiten badu, datu zaharrak alde batera geratzen dira eta aplikazioak geldituta.",
  "dbdump.importDone": "Datu-basea inportatu da.",
  "dbdump.importRefused.busy": "Beste babeskopia edo leheneratze bat martxan dago. Saiatu berriro amaitzean.",
  "dbdump.importRefused.notRunning": "Abiarazi edukiontzia lehenik; inportazioak zerbitzaria martxan behar du.",
  "dbdump.importRefused.engineMismatch": "Iraulketa hau edukiontziak darabilena ez den beste datu-base mota batetik dator.",
  "dbdump.importRefused.noDataMount": "BombVault-ek ezin du edukiontzi honen datuen karpetara iritsi, beraz ezin du segurtasunez alde batera eraman. Inportatu iraulketa eskuz, larrialdi-paketeak azaltzen duen moduan.",
  "dbdump.importRefused.version": "Zerbitzariak {server} bertsioa darabil, iraulketa {dump} bertsiokoa da. Erabili {dump} bertsioa edo berriagoa duen irudi bat inportazio honetarako.",
  "dbdump.importRefused.versionSameMajor": "Zerbitzariak {server} bertsioa darabil, iraulketa {dump} bertsiokoa da. MySQL eta MariaDB-k iraulketa bat datorren bertsio nagusian bakarrik inportatzen dute, beraz erabili {dump} bertsioa duen irudi bat inportazio honetarako.",
  "dbdump.importRefused.damaged": "Iraulketa hau hondatuta dago eta ezin da inportatu.",
