  "repos.locationLocked": "Kokapena ezin da mugitu zerbaitek hona kopiatzen duen bitartean: orain arte idatzitako guztia dagoen lekuan geratzen da, beraz hurrengo kopiak biltegi huts batean lortuko luke arrakasta. Gehitu bigarren bat eta seinalatu elementuak hara.",
