  "placementCode.destinationHoldsBackups": "Kokapena ezin da mugitu hona babeskopiak egiten diren bitartean: orain arte idatzitako guztia atzean geratuko litzateke, eta hurrengo babeskopiak biltegi huts bat aurkituko luke. Gehitu bigarren helmuga bat eta zuzendu elementuak hara.",
  "placementCode.backupsNotThere": "Hemen gordetako babeskopiak ez dira irekitzen aldatutako konexioarekin, beraz ez da ezer gorde. Egiaztatu sartu duzuna. Babeskopiak lekuz aldatu badira, gehitu bigarren helmuga bat leku berrirako.",
  "placementCode.lastCopies": "Sarrerek beren babeskopia bakarra galduko lukete, eta zerrenda aldatu egin da erakutsi zenetik. Egiaztatu berriro.",
  "placementCode.nothingToErase": "Hemengo babeskopietatik bat ere ezin da ezabatu. Kendu helmuga horren ordez, eta mantendu babeskopiak.",
  "placementCode.moveSamePlace": "Domeinuak badu bere kopia han. Aukeratu beste helmuga bat.",
  "placementCode.moveSectionThere": "Helmuga horrek badu domeinu honen kopia propioa. Aukeratu beste helmuga bat.",
  "placementCode.moveDirectRepo": "Sarrerek zuzenean toki honetara egiten dute babeskopia, etxeko kopiarik gabe, beraz domeinua ezin da mugitu. Aldatu lehenik sarrera horiek Lokala aukerara.",
  "placementCode.moveSignIn": "Bi tokiek modu berean hasten dute saioa, baina kredentzial desberdinekin, eta kopia batek bietako bat bakarrik erabil dezake. Mugitu lehenik domeinua zerbitzari honetako karpeta batera, eta handik toki berrira.",
  "placementCode.moveRunning": "Domeinu hau mugitzen ari da jada. Laburpenean jarrai dezakezu.",

