  "anomaly.sentence.newDataRewrite": "{name} elementuak {bytes} berridatzi ditu babeskopia bakar batean, gordetzen den guztiaren erdia gutxienez ({source}). Hainbeste aldatu ez baduzu, egiaztatu fitxategiak zifratu edo ordeztu diren.",
  "anomaly.sentence.newDataRenamed": "{name} elementuaren fitxategi guztiak berriak dirudite lehenagoko babeskopia bat egon arren, eta {source} kopurutik {bytes} berriro gorde dira. Aldi berean izena aldatu eta berridatzitako fitxategiak ohikoak dira ransomwarean. Egiaztatu fitxategiak ezer baino lehen.",
  "anomaly.sentence.newDataFull": "BombVaultek {name} elementuaren fitxategi guztiak berriro irakurri ditu lehenagoko babeskopiarik bat ez zetorrelako (biltegi berria, karpeta berriak edo zifratze aldatua). Gordetako datu berriak: {bytes}.",
