  "overview.history.hint": "Exekuzio bakoitza bere emaitza, iraupen eta arrazoiarekin; klik eginez irekitzen da. Erregistroak lerro bakoitza bere orduarekin erakusten du, BombVaultek idazten duen bezala.",
