  "overview.coverage.counted": "Beste toki guztietan bezala kontatzen da: aktibatutako atalen elementuak, oraindik instalatuta daudenak eta baztertu ez dituzunak. Behean hurrengo programatutako exekuzioak estaltzen ez duen guztia dago, baztertutako elementuak eta datu multzo bakarrak barne.",
