  "overview.customizeHint": "Txartel bat bere barratik arrastatu daiteke berrordenatzeko, behealdeko izkinako puntuan tamaina alda daiteke, edo ezkutatu behar ez bada. Nabigatzaile honetan gordetzen da.",
